 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])

    # A repeated horizontal color strip gives the ordered stack palette.
    key = None
    for r in range(h - 1):
        cells = [(c, grid[r][c]) for c in range(w) if grid[r][c] != 0]
        if len(cells) < 2 or any(grid[r + 1][c] != v for c, v in cells):
            continue
        cols = [c for c, _ in cells]
        if cols != list(range(cols[0], cols[-1] + 1)):
            continue
        rr = r + 2
        while rr < h and all(grid[rr][c] == v for c, v in cells):
            rr += 1
        if rr - r >= 2:
            key = [v for _, v in cells]
            break
    if key is None:
        raise ValueError('repeated color key not found')

    # The largest 8-connected component of color 1 is the reference motif.
    seen, comps = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            q, comp = deque([(r, c)]), []
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        yy, xx = y + dy, x + dx
                        if (0 <= yy < h and 0 <= xx < w and
                                grid[yy][xx] == 1 and (yy, xx) not in seen):
                            seen.add((yy, xx))
                            q.append((yy, xx))
            comps.append(comp)
    if not comps:
        raise ValueError('color-1 motif not found')
    comp = max(comps, key=len)
    top, left = min(y for y, x in comp), min(x for y, x in comp)
    mh = max(y for y, x in comp) - top + 1
    shape = {(y - top, x - left) for y, x in comp}

    out = [[0] * w for _ in range(h)]
    start = top - key.index(1) * mh
    for i, color in enumerate(key):
        y0 = start + i * mh
        for dy, dx in shape:
            y, x = y0 + dy, left + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out
